def transform(grid):
    # Find distinct values
    values = set()
    for row in grid:
        for cell in row:
            values.add(cell)

    if len(values) == 0:
        return grid
    if len(values) == 1:
        return [[0 for _ in row] for row in grid]

    sorted_values = sorted(values)
    smaller = sorted_values[0]
    larger = sorted_values[1]

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == smaller:
                new_row.append(larger)
            else:
                new_row.append(0)
        result.append(new_row)
    return result

