import collections

def transform(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])

    # Background color (most frequent)
    counts = collections.Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Horizontal separators: full rows of same non-background color
    h_seps = set()
    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)):
            if grid[r][0] != bg:
                h_seps.add(r)
    h_seps = sorted(list(h_seps))

    # Vertical separators: full columns of same non-background color
    v_seps = set()
    for c in range(W):
        col_val = grid[0][c]
        if all(grid[r][c] == col_val for r in range(H)):
            if col_val != bg:
                v_seps.add(c)
    v_seps = sorted(list(v_seps))

    # Get region ranges
    def get_ranges(seps, limit):
        ranges = []
        start = 0
        for s in seps:
            if start < s:
                ranges.append((start, s))
            start = s + 1
        if start < limit:
            ranges.append((start, limit))
        return ranges

    h_regs = get_ranges(h_seps, H)
    v_regs = get_ranges(v_seps, W)

    # Find source region with most non-background content
    source_subgrid = None
    max_non_bg = -1

    for hi in range(len(h_regs)):
        for vi in range(len(v_regs)):
            r_start, r_end = h_regs[hi]
            c_start, c_end = v_regs[vi]

            # Count non-bg cells in this region
            non_bg = 0
            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    if grid[r][c] != bg:
                        non_bg += 1

            if non_bg > max_non_bg:
                max_non_bg = non_bg
                source_subgrid = [grid[r][c_start:c_end] for r in range(r_start, r_end)]

    if source_subgrid is None:
        return grid

    # Apply source pattern to all regions
    for hi in range(len(h_regs)):
        for vi in range(len(v_regs)):
            r_start, r_end = h_regs[hi]
            c_start, c_end = v_regs[vi]

            sr_start = r_start
            sc_start = c_start

            for si, row in enumerate(source_subgrid):
                for scj, val in enumerate(row):
                    grid[sr_start + si][sc_start + scj] = val

    return grid

from collections import Counter

def transform(grid):
    rows = len(grid)
    if rows == 0: return grid
    cols = len(grid[0])

    # Identify background color
    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1
    bg = counts.most_common(1)[0][0]

    # Work on a copy
    res = [row[:] for row in grid]

    # Group non-background pixels by color
    groups = {}
    for r in range(rows):
        for c in range(cols):
            col_val = grid[r][c]
            if col_val != bg:
                if col_val not in groups:
                    groups[col_val] = []
                groups[col_val].append((r, c))

    # Process each color group
    visited = set()

    for color in groups:
        pixels = groups[color]

        for r, c in pixels:
            if (r, c) in visited:
                continue

            # BFS to find diagonal connected component
            component = set()
            component.add((r, c))
            visited.add((r, c))
            queue = [(r, c)]

            idx = 0
            while idx < len(queue):
                rr, cc = queue[idx]
                idx += 1

                # Check 4 diagonal neighbors
                for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color:
                            if (nr, nc) not in component:
                                component.add((nr, nc))
                                visited.add((nr, nc))
                                queue.append((nr, nc))

            # Logic: Only extend if component size > 1
            if len(component) > 1:
                comp_list = list(component)

                # Identify endpoints: pixels with exactly 1 neighbor in component
                degrees = {}
                for rr, cc in comp_list:
                    deg = 0
                    for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                        nr, nc = rr + dr, cc + dc
                        if (nr, nc) in component:
                            deg += 1
                    degrees[(rr, cc)] = deg

                # Extend from endpoints
                for start_node, deg in degrees.items():
                    if deg == 1:
                        # Find neighbor
                        neighbor = None
                        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
                            nr, nc = start_node[0] + dr, start_node[1] + dc
                            if (nr, nc) in component:
                                neighbor = (nr, nc)
                                break

                        if neighbor:
                            sr, sc = start_node
                            nr, nc = neighbor

                            # Direction away from neighbor
                            dr_dir = sr - nr
                            dc_dir = sc - nc

                            curr_r, curr_c = sr, sc

                            # Trace path
                            while True:
                                nearest_r = curr_r + dr_dir
                                nearest_c = curr_c + dc_dir

                                # Boundaries
                                if not (0 <= nearest_r < rows and 0 <= nearest_c < cols):
                                    break

                                # Obstruction (non-background)
                                if res[nearest_r][nearest_c] != bg:
                                    break

                                # Extend line
                                res[nearest_r][nearest_c] = color
                                curr_r, curr_c = nearest_r, nearest_c

    return res

