            for j in range(i + 1, len(pixel_list)):
                r2, c2 = pixel_list[j]
                dr, dc = r2 - r1, c2 - c1

                if abs(dr) == 1 and abs(dc) == 1:
                    # Found diagonal pair, extend beams from both pixels
                    # Direction from r1,c1 to r2,c2
                    curr_r, curr_c = r1, c1
                    while True:
                        nr, nc = curr_r - dr, curr_c - dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if res[nr][nc] != bg:
                            break
                        res[nr][nc] = color
                        curr_r, curr_c = nr, nc

                    curr_r, curr_c = r2, c2
                    while True:
                        nr, nc = curr_r + dr, curr_c + dc
                        if not (0 <= nr < rows and 0 <= nc < cols):
                            break
                        if res[nr][nc] != bg:
                            break
                        res[nr][nc] = color
                        curr_r, curr_c = nr, nc

    return res

def transform(grid):
    from collections import defaultdict

    # Collect non-zero groups
    groups = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v != 0:
                groups[v].append((r, c))

    if len(groups) == 0:
        return grid

    # Detect invariant: sum (r+c) or diff (r-c) is constant per value
    key_func = None
    for v in groups:
        coords = groups[v]
        sums = set(r + c for r, c in coords)
        diffs = set(r - c for r, c in coords)

        if len(sums) == 1 and len(diffs) > 1:
            key_func = lambda r, c: r + c
            break
        elif len(diffs) == 1 and len(sums) > 1:
            key_func = lambda r, c: r - c
            break

    if key_func is None:
        key_func = lambda r, c: r - c

    L = len(groups)
    residue_map = {}
    for v in groups:
        r, c = groups[v][0]
        k = key_func(r, c)
        residue_map[k % L] = v

    # Build output grid
    output_grid = []  # Fixed: initialize before loop
    for r in range(len(grid)):
        row = []
        for c in range(len(grid[0])):
            k = key_func(r, c)
            val = residue_map.get(k % L)
            row.append(val)
        output_grid.append(row)  # Now appends to defined list
    return output_grid

