    for r in range(rows):
        for c in range(cols):
            val = result[r][c]
            if val != background:
                if val not in color_coords:
                    color_coords[val] = []
                color_coords[val].append((r, c))

    for color, coords in color_coords.items():
        visited = set()
        for start in coords:
            if start in visited:
                continue
            comp = []
            stack = [start]
            while stack:
                curr = stack.pop()
                if curr in visited:
                    continue
                visited.add(curr)
                comp.append(curr)
                r, c = curr
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if result[nr][nc] == color:
                            stack.append((nr, nc))

            r_set = [p[0] for p in comp]
            c_set = [p[1] for p in comp]
            r_min, r_max = min(r_set), max(r_set)
            c_min, c_max = min(c_set), max(c_set)

            if r_max - r_min < 2 and c_max - c_min < 2:
                continue

            border_ok = True
            for r in range(r_min, r_max + 1):
                for c in range(c_min, c_max + 1):
                    if r == r_min or r == r_max or c == c_min or c == c_max:
                        if result[r][c] != color:
                            border_ok = False
                            break
