def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Determine background color (most frequent)
    from collections import Counter
    vals = [x for r in grid for x in r]
    bg = Counter(vals).most_common(1)[0][0]

    visited = [[False] * cols for _ in range(rows)]

    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != bg and not visited[r][c]:
                # Found a new component, find its bounding box and check if it's a frame
                # We store all cells in this component
                comp_cells = []
                q = [(r, c)]
                visited[r][c] = True
                while q:
                    curr_r, curr_c = q.pop(0)
                    comp_cells.append((curr_r, curr_c))
                    for nr, nc in get_neighbors(curr_r, curr_c):
                        if grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

                # Calculate bounding box
                r_min = min(p[0] for p in comp_cells)
                r_max = max(p[0] for p in comp_cells)
                c_min = min(p[1] for p in comp_cells)
                c_max = max(p[1] for p in comp_cells)

                # Check if it forms a hollow frame (border is color, interior is bg)
                # Interior dimensions
                inner_h = r_max - r_min - 1
                inner_w = c_max - c_min - 1

                # If interior is empty (too small to be a frame or just a line), skip filling
                # We require at least 1x1 interior to be a valid frame to be filled in ARC style
                if inner_h <= 0 or inner_w <= 0:
                    continue

                # Check border
                is_frame = True
                # Check exterior border
                for k in range(r_min, r_max + 1):
                    for j in range(c_min, c_max + 1):
                        # Check corners or edges
                        if k == r_min or k == r_max or j == c_min or j == c_max:
                            if grid[k][j] != color:
                                is_frame = False
                                break
                    if not is_frame:
                        break

                if not is_frame:
                    continue

                # Check interior is all background
                for k in range(r_min + 1, r_max):
                    for l in range(c_min + 1, c_max):
                        if grid[k][l] != bg:
                            is_frame = False
                            break
                    if not is_frame:
                        break

                if is_frame:
                    # Determine fill color based on interior dimensions parity
                    # Odd (1, 3, 5...) -> 7
                    # Even (2, 4...) -> 2
                    if (inner_w % 2 != 0) or (inner_h % 2 != 0):
                        fill_color = 7
