    # Copy visited to use across iterations
    used = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == bg_color and not used[i][j]:
                # BFS to find connected component
                component = []
                stack = [(i, j)]
                used[i][j] = True

                while stack:
                    r, c = stack.pop()
                    component.append((r, c))

                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == bg_color and not used[nr][nc]:
                                used[nr][nc] = True
                                stack.append((nr, nc))

                if not component:
                    continue

                # Compute bounding box
                min_r = min(p[0] for p in component)
                max_r = max(p[0] for p in component)
                min_c = min(p[1] for p in component)
                max_c = max(p[1] for p in component)

                # Check if it's a perfect rectangle (all cells in bbox are in component)
                rect_area = (max_r - min_r + 1) * (max_c - min_c + 1)
                if len(component) != rect_area:
                    continue

                # Check if the bounding box PLUS one layer of walls around it exists
                # - check top row (min_r - 1) has walls above all columns min_c to max_c
                # - check bottom row (max_r + 1) has walls below all columns min_c to max_c
                # - check left column (min_c - 1) has walls to left for all rows min_r to max_r
                # - check right column (max_c + 1) has walls to right for all rows min_r to max_r

                is_enclosed = True

                # Check top
                if min_r > 0:
                    for c in range(min_c, max_c + 1):
                        if grid[min_r - 1][c] == bg_color:
                            is_enclosed = False
                            break
                else:
                    is_enclosed = False

                if is_enclosed:
                    # Check bottom
                    if max_r < n - 1:
                        for c in range(min_c, max_c + 1):
                            if grid[max_r + 1][c] == bg_color:
                                is_enclosed = False
                                break
                    else:
                        is_enclosed = False

                if is_enclosed:
                    # Check left
                    if min_c > 0:
                        for r in range(min_r, max_r + 1):
                            if grid[r][min_c - 1] == bg_color:
                                is_enclosed = False
                                break
                    else:
                        is_enclosed = False

                if is_enclosed:
                    # Check right
                    if max_c < m - 1:
