def transform(grid):
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    data = [[int(grid[r][c]) for c in range(W)] for r in range(H)]

    # Find background (most frequent)
    counts = {}
    for r in range(H):
        for c in range(W):
            v = data[r][c]
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find frame color (hollow rectangle)
    frame_color = None
    max_area = 0
    rmin_frame, rmax_frame, cmin_frame, cmax_frame = -1, -1, -1, -1

    for color in set(int(x) for row in data for x in row):
        if color == bg:
            continue

        pixels = []
        for r in range(H):
            for c in range(W):
                if data[r][c] == color:
                    pixels.append((r, c))

        if not pixels:
            continue

        r_min = min(p[0] for p in pixels)
        r_max = max(p[0] for p in pixels)
        c_min = min(p[1] for p in pixels)
        c_max = max(p[1] for p in pixels)

        # Check if it's a hollow frame (only border has color)
        is_hollow = True
        for r in range(r_min, r_max + 1):
            for c in range(c_min, c_max + 1):
                if data[r][c] == color:
                    if r != r_min and r != r_max and c != c_min and c != c_max:
                        is_hollow = False
                        break
            if not is_hollow:
                break

        if is_hollow:
            area = (r_max - r_min + 1) * (c_max - c_min + 1)
            if area > max_area:
                max_area = area
                frame_color = color
                rmin_frame, rmax_frame, cmin_frame, cmax_frame = r_min, r_max, c_min, c_max

    if frame_color is None:
        return data

    # Object dimensions to copy into
    inner_h = rmax_frame - rmin_frame - 1
    inner_w = cmax_frame - cmin_frame - 1

    if inner_h <= 0 or inner_w <= 0:
        return data

    # Collect all object pixels (non-bg, non-frame)
    obj_pixels = []
    for r in range(H):
        for c in range(W):
            if data[r][c] != bg and data[r][c] != frame_color:
                obj_pixels.append((r, c))

    # Object bounding box
    if not obj_pixels:
        return data

    o_rmin = min(p[0] for p in obj_pixels)
    o_rmax = max(p[0] for p in obj_pixels)
    o_cmin = min(p[1] for p in obj_pixels)
    o_cmax = max(p[1] for p in obj_pixels)

    # Get object subgrid
    src_h = o_rmax - o_rmin + 1
    src_w = o_cmax - o_cmin + 1

    src_grid = []
    for r in range(src_h):
        row = []
        for c in range(src_w):
            row.append(data[o_rmin + r][o_cmin + c])
        src_grid.append(row)

    # Scale to inner dimensions using nearest-neighbor with proper up/down scaling
    def scale_grid(src, tgt_h, tgt_w):
        if tgt_h <= 0 or tgt_w <= 0:
            return []
        res = []
        for tr in range(tgt_h):
            # For nearest neighbor, map target to source by finding closest source row
            sr = int(tr * src_h / tgt_h)
            sr = max(0, min(sr, src_h - 1))
            row = []
            for tc in range(tgt_w):
                sc = int(tc * src_w / tgt_w)
                sc = max(0, min(sc, src_w - 1))
                row.append(src[sr][sc])
            res.append(row)
        return res

    scaled = scale_grid(src_grid, inner_h, inner_w)

    # Build output
    out_h = rmax_frame - rmin_frame + 1
    out_w = cmax_frame - cmin_frame + 1

    output = [[frame_color] * out_w for _ in range(out_h)]

    for r in range(inner_h):
        for c in range(inner_w):
            output[r + 1][c + 1] = scaled[r][c]

    return output

