        lambda r, c, H: r % H,   # Horizontal periodicity (rows are constant)
        lambda r, c, H: (c - r) % H, # Diagonal periodicity (diagonals are constant)
        lambda r, c, H: (r + c) % H  # Anti-diagonal periodicity
    ]

