                triggers.append((r, c))

    # Create a copy of the grid
    new_grid = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])

    # Check neighbors for '2's and update background pixels
    for r in range(rows):
        for c in range(cols):
            val = new_grid[r][c]
            # If pixel is background and is a neighbor of any '2'
            if val == bg_color:
                is_neighbor = False
                for tr, tc in triggers:
                    # Check 8-connectivity (excluding self, but val != 2 check handles safety)
                    if abs(r - tr) <= 1 and abs(c - tc) <= 1:
                        is_neighbor = True
                        break
                if is_neighbor:
                    new_grid[r][c] = 1

    return new_grid

def transform(grid):
    if not grid or not grid[0]:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                continue
            if (r, c) in visited:
                continue

            # Identify connected component
            color = grid[r][c]
            component = []
            stack = [(r, c)]
            # Using a temporary set for component traversal
            current_visited = {(r, c)}
            component.append((r, c))

            # BFS/DFS stack-based search
            idx = 0
            while idx < len(stack):
                curr_r, curr_c = stack[idx]
                idx += 1

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color and (nr, nc) not in current_visited:
                            current_visited.add((nr, nc))
                            component.append((nr, nc))
                            stack.append((nr, nc))

            # Mark cells as visited so we don't process them again
            visited.update(current_visited)

            # Determine bounding box
            min_r = min(p[0] for p in component)
            max_r = max(p[0] for p in component)
            min_c = min(p[1] for p in component)
            max_c = max(p[1] for p in component)

            # Fill interior with 2
            for rr in range(min_r, max_r + 1):
                for cc in range(min_c, max_c + 1):
                    if (rr, cc) in current_visited:
                        # Check if border
                        if rr != min_r and rr != max_r and cc != min_c and cc != max_c:
                            grid[rr][cc] = 2

    return grid

def transform(grid):
    # Identify background color (most frequent)
    bg_counts = {}
    for row in grid:
        for val in row:
            bg_counts[val] = bg_counts.get(val, 0) + 1
    bg = max(bg_counts, key=bg_counts.get)

    # Create output grid initialized with background color
    out = [[bg for _ in range(len(grid[0]))] for _ in range(len(grid))]

    # Identify non-background objects
    color_positions = {}
    for r_idx, row in enumerate(grid):
        for c_idx, val in enumerate(row):
            if val != bg:
                if val not in color_positions:
                    color_positions[val] = []
                color_positions[val].append((r_idx, c_idx))

    # Sort by number of pixels: Source (largest) and Target (smallest, anchor)
    colors_by_area = sorted(color_positions.items(), key=lambda item: len(item[1]), reverse=True)

    if len(colors_by_area) < 2:
        return out

    source_color, source_pixels = colors_by_area[0]
    target_color, target_pixels = colors_by_area[1]
    if not target_pixels:
        return out

    # Anchor Logic: The single Target pixel corresponds to the Top-Right corner of the new shape
    target_anchor_row, target_anchor_col = target_pixels[0]

    # Extract Source Geometry (Bounding Box and Mask)
    src_r_min = min(p[0] for p in source_pixels)
    src_r_max = max(p[0] for p in source_pixels)
    src_c_min = min(p[1] for p in source_pixels)
    src_c_max = max(p[1] for p in source_pixels)

    src_h = src_r_max - src_r_min + 1
    src_w = src_c_max - src_c_min + 1

    # Create a binary mask of the Source shape relative to its top-left
    src_mask = [[False] * src_w for _ in range(src_h)]
    for r, c in source_pixels:
        src_mask[r - src_r_min][c - src_c_min] = True

    # 1. Preserve Source Shape (draw Source Color at Source Location)
    for r in range(src_r_min, src_r_max + 1):
        for c in range(src_c_min, src_c_max + 1):
            if src_mask[r - src_r_min][c - src_c_min]:
                out[r][c] = source_color

    # 2. Draw New Target Shape at (Target Anchor as Top-Right)
    # If Top-Right is at (R, C) and Width is W, then Top-Left is at (R, C - W + 1)
    new_tl_r = target_anchor_row
    new_tl_c = target_anchor_col - src_w + 1

    for r_rel in range(src_h):
        for c_rel in range(src_w):
            if src_mask[r_rel][c_rel]:
                r_abs = new_tl_r + r_rel
                c_abs = new_tl_c + c_rel
                if 0 <= r_abs < len(out) and 0 <= c_abs < len(out[0]):
                    out[r_abs][c_abs] = target_color

    return out

def transform(grid):
    if not grid: return grid
    bg = grid[0][0]
    H, W = len(grid), len(grid[0])

    visited = set()
    components = []

    # Identify connected components of non-background cells
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and (r, c) not in visited:
                # DFS to find component
                stack = [(r, c)]
                visited.add((r, c))
                comp_cells = []
                min_r, max_r, min_c, max_c = r, r, c, c

                while stack:
                    curr_r, curr_c = stack.pop()
                    comp_cells.append((curr_r, curr_c))
                    min_r = min(min_r, curr_r)
                    max_r = max(max_r, curr_r)
                    min_c = min(min_c, curr_c)
                    max_c = max(max_c, curr_c)

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == grid[r][c] and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                components.append({
                    'cells': comp_cells,
                    'color': grid[r][c],
                    'area': len(comp_cells),
                    'bbox': (min_r, max_r, min_c, max_c)
                })

    # Separate Tokens and Objects
    # Threshold area 2 separates small markers from larger blocks
    tokens = [c for c in components if c['area'] <= 2]
    objects = [c for c in components if c['area'] > 2]

    # Determine Legend Line (Row or Column containing Tokens)
    token_coords = set()
    for t in tokens:
        for r, c in t['cells']:
            token_coords.add((r, c))

    legend_row = None
    legend_col = None
    rows = set(r for r, c in token_coords)
    cols = set(c for r, c in token_coords)

    if len(rows) == 1:
        legend_row = rows.pop()
        legend_line = 'row'
    elif len(cols) == 1:
        legend_col = cols.pop()
        legend_line = 'col'

    # Token Value Map for lookup
    token_vals = {} 
    for t in tokens:
        for r, c in t['cells']:
            token_vals[(r, c)] = t['color']

    # Apply recoloring to objects
    if legend_line is not None:
        for comp in objects:
            min_r, max_r, min_c, max_c = comp['bbox']
            target_color = None

            if legend_line == 'row':
                # Check for overlap in columns with Legend at 'legend_row'
                candidates = []
                for (tr, tc), v in token_vals.items():
                    if tr == legend_row and min_c <= tc <= max_c:
                        candidates.append(v)
                if candidates:
                    target_color = candidates[0]
                else:
                    # Fallback: Closest token to object center
                    center_c = (min_c + max_c) / 2.0
                    best_dist = float('inf')
                    for (tr, tc), v in token_vals.items():
                        if tr == legend_row:
                            d = abs(tc - center_c)
                            if d < best_dist:
                                best_dist = d
                                target_color = v
            else: # legend_line == 'col'
                # Check for overlap in rows with Legend at 'legend_col'
                candidates = []
                for (tr, tc), v in token_vals.items():
                    if tc == legend_col and min_r <= tr <= max_r:
                        candidates.append(v)
                if candidates:
                    target_color = candidates[0]
                else:
                    # Fallback: Closest token
                    center_r = (min_r + max_r) / 2.0
                    best_dist = float('inf')
                    for (tr, tc), v in token_vals.items():
                        if tc == legend_col:
                            d = abs(tr - center_r)
                            if d < best_dist:
                                best_dist = d
                                target_color = v

            if target_color is not None:
                for r, c in comp['cells']:
                    grid[r][c] = target_color

    return grid
